<script>
 import { onMount } from 'svelte';
 import { Search, Plus, Link2, Trash2, ExternalLink, Eye, Layers3 } from 'lucide-svelte';
 import Modal from '../../../components/Modal.svelte'; import AddModal from '../modals/AddModal.svelte';
 import { getLinkTrees, createLinkTree, deleteLinkTree, deleteAllLinkTrees } from '../api/linkTreeApi.js';
 import { setLinkTrees, linkTrees } from '../states/linkTreesStore.js';
 import { confirmDialog, showErrorDialog, showSuccessDialog } from '../../../helpers/toolsHelper.js'; import { navigate } from '../../../router.js';
 let items=$state([]); let loading=$state(true); let search=$state(''); let mineOnly=$state(false); let showAdd=$state(false);
 let filtered = $derived(items.filter(x => (x.title||'').toLowerCase().includes(search.toLowerCase()) && (!mineOnly || x.is_me || x.is_mine)));
 async function load(){loading=true;try{const r=await getLinkTrees();items=r.data?.link_trees||[];setLinkTrees(items)}catch(e){await showErrorDialog(e.message)}finally{loading=false}}
 onMount(load);
 async function add(data){try{await createLinkTree(data);showAdd=false;await showSuccessDialog('Link Tree berhasil dibuat.');await load()}catch(e){await showErrorDialog(e.message)}}
 async function remove(item){if(!await confirmDialog(`Hapus "${item.title}"?`))return;try{await deleteLinkTree(item.id);await load();await showSuccessDialog('Link Tree dihapus.')}catch(e){await showErrorDialog(e.message)}}
 async function removeAll(){if(!items.length||!await confirmDialog('Semua Link Tree akan dihapus.'))return;try{await deleteAllLinkTrees();await load();await showSuccessDialog('Semua Link Tree dihapus.')}catch(e){await showErrorDialog(e.message)}}
</script>
<svelte:head><title>Semua Link Tree · Delcom Link Tree</title></svelte:head>
<div class="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="mb-2 text-sm font-bold text-indigo-600">RUANG TAUTANMU</p><h1 class="text-3xl font-extrabold tracking-tight sm:text-4xl">Semua Link Tree</h1><p class="mt-2 text-slate-500">Atur dan bagikan semua tautan pentingmu.</p></div><button class="btn btn-primary" onclick={()=>showAdd=true}><Plus size={18}/> Buat Link Tree</button></div>
<div class="mb-6 grid gap-4 sm:grid-cols-3"><div class="panel flex items-center gap-4 p-5"><div class="rounded-xl bg-indigo-50 p-3 text-indigo-600"><Layers3 size={22}/></div><div><p class="text-sm text-slate-500">Total Link Tree</p><p class="text-2xl font-extrabold">{items.length}</p></div></div><div class="panel flex items-center gap-4 p-5"><div class="rounded-xl bg-emerald-50 p-3 text-emerald-600"><Eye size={22}/></div><div><p class="text-sm text-slate-500">Publik</p><p class="text-2xl font-extrabold">{items.filter(x=>x.type==='public').length}</p></div></div><div class="panel flex items-center gap-4 p-5"><div class="rounded-xl bg-violet-50 p-3 text-violet-600"><Link2 size={22}/></div><div><p class="text-sm text-slate-500">Total tautan</p><p class="text-2xl font-extrabold">{items.reduce((sum,x)=>sum+(x.items?.length||0),0)}</p></div></div></div>
<div class="panel p-5 sm:p-6"><div class="mb-5 flex flex-col gap-3 sm:flex-row"><div class="relative flex-1"><Search size={18} class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input class="field pl-10" bind:value={search} placeholder="Cari Link Tree..."/></div><label class="flex items-center gap-2 rounded-xl bg-slate-50 px-4 text-sm font-semibold"><input type="checkbox" bind:checked={mineOnly}/> Milik saya</label><button class="btn btn-danger" onclick={removeAll} disabled={!items.length}><Trash2 size={16}/> Hapus semua</button></div>
{#if loading}<div class="py-12 text-center text-slate-500">Memuat Link Tree...</div>{:else if !filtered.length}<div class="py-14 text-center"><div class="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600"><Link2 size={26}/></div><h2 class="font-extrabold">Belum ada Link Tree</h2><p class="mt-2 text-sm text-slate-500">Buat Link Tree pertamamu atau ubah kata pencarian.</p><button class="btn btn-primary mt-5" onclick={()=>showAdd=true}><Plus size={17}/> Buat Link Tree</button></div>{:else}<div class="grid gap-4 lg:grid-cols-2">{#each filtered as item (item.id)}<article class="rounded-2xl border border-slate-200 p-5 transition hover:border-indigo-200 hover:shadow-md"><div class="flex items-start justify-between gap-3"><div class="flex min-w-0 items-start gap-3"><div class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><Link2 size={23}/></div><div class="min-w-0"><h2 class="truncate text-lg font-extrabold">{item.title}</h2><p class="mt-1 line-clamp-2 text-sm text-slate-500">{item.description||'Belum ada deskripsi.'}</p><span class="badge mt-3">{item.type||'public'}</span></div></div><button aria-label={'Hapus '+item.title} class="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-600" onclick={()=>remove(item)}><Trash2 size={17}/></button></div><div class="mt-5 flex items-center justify-between border-t border-slate-100 pt-4"><span class="text-xs text-slate-500">{item.items?.length||0} tautan</span><button class="btn btn-muted" onclick={()=>navigate(`/link-trees/${item.id}`)}>Kelola <ExternalLink size={15}/></button></div></article>{/each}</div>{/if}</div>
{#if showAdd}<Modal title="Buat Link Tree" onClose={()=>showAdd=false}>{#snippet children()}<AddModal onClose={()=>showAdd=false} onSave={add}/>{/snippet}</Modal>{/if}
